import{_ as e,o as n,c as a,a5 as o}from"./chunks/framework.Cooo9kuv.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"856-批量获取视频音频时长添加到文件名中-可导出到excel支持子孙文件夹下操作","日期":"2026-04-14T00:00:00.000Z","修改日期":"2026-04-14T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["文件及文件夹批处理","音频视频批处理"],"标签":["Excel记录","批量改名","文件夹穿透","时长导出","音视频时长"]},"headers":[{"level":3,"title":"功能特点","slug":"功能特点","link":"#功能特点","children":[]},{"level":3,"title":"基本操作指南","slug":"基本操作指南","link":"#基本操作指南","children":[]},{"level":3,"title":"使用场景例子展示","slug":"使用场景例子展示","link":"#使用场景例子展示","children":[]},{"level":3,"title":"常见问题解答","slug":"常见问题解答","link":"#常见问题解答","children":[]},{"level":3,"title":"程序截图","slug":"程序截图","link":"#程序截图","children":[]},{"level":3,"title":"程序使用环境及相关说明","slug":"程序使用环境及相关说明","link":"#程序使用环境及相关说明","children":[]},{"level":3,"title":"程序使用说明","slug":"程序使用说明","link":"#程序使用说明","children":[]}],"relativePath":"md/文件及文件夹批处理/856-批量获取视频音频时长添加到文件名中-可导出到excel支持子孙文件夹下操作.md","filePath":"md/文件及文件夹批处理/856-批量获取视频音频时长添加到文件名中-可导出到excel支持子孙文件夹下操作.md"}'),l={name:"md/文件及文件夹批处理/856-批量获取视频音频时长添加到文件名中-可导出到excel支持子孙文件夹下操作.md"};function p(r,t,s,c,i,g){return n(),a("div",null,[...t[0]||(t[0]=[o('<p>批量将音频或视频时长写进文件名并导出Excel清单的小工具。</p><p>自动读取每个媒体的时长，按你选的格式加到文件名上，还会在程序所在目录生成一份Excel记录。</p><p>【1】、支持的文件格式：常见音视频格式</p><p>【2】、是否支持子文件夹穿透：支持</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251208230407176520624766654.jpg" alt=""></p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251208225557176520575781340.png" alt=""></p><p>支持常见音视频格式；</p><p>可选穿透子文件夹，把多层目录一起处理；</p><p>可选是否改名，想只生成记录也可以；</p><p>时长格式支持标准00:00:00或“X分X秒”并可选择毫秒；</p><p>每个文件夹都会产出带原名、新名、时长、路径的Excel。</p><h3 id="基本操作指南" tabindex="-1">基本操作指南 <a class="header-anchor" href="#基本操作指南" aria-label="Permalink to &quot;基本操作指南&quot;">​</a></h3><p>在输入框里填或点击“选择”需要处理的文件夹。</p><p>勾选是否穿透子文件夹，决定要不要处理子目录。</p><p>选择是否修改文件名，想要在文件名里加入时长就选“是”，只想导出Excel就选“否”。</p><p>选择是否显示毫秒，以及Excel时长格式是标准“00:00:00”还是原有分钟秒格式。</p><p>点“开始程序”后，工具会依次读取时长并按设定改名，同时在界面显示进度。</p><p>处理完每个文件夹，会在脚本目录生成一份包含原文件名、新文件名、时长、文件路径的Excel。</p><h3 id="使用场景例子展示" tabindex="-1">使用场景例子展示 <a class="header-anchor" href="#使用场景例子展示" aria-label="Permalink to &quot;使用场景例子展示&quot;">​</a></h3><p>当你有一批课程视频想在文件名里带上播放时长，选择包含这些视频的文件夹，保持“修改文件名”为“是”，时长格式选标准00:00:00或分钟秒格式，点击开始即可，处理完后文件名会自动附上时长，同时得到一份Excel清单。若只想拿到时长统计表不改名，把“修改文件名”调为“否”，运行后直接查看生成的Excel。</p><p><strong>比如A文件夹下是下方展示的结构</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251208230327176520620794959.png" alt=""></p><p><strong>处理后的效果如下所示</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251208230350176520623023302.png" alt=""></p><p><strong>excel文档示例，每个文件夹都会生成一个excel，保存在程序所在文件夹下</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251208230536176520633694205.png" alt=""></p><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h3><p><strong>Q</strong>：双击后没有反应怎么办？<br> A：确认系统是64位Windows且文件已完整解压，若有安全软件拦截，把程序文件夹加入信任后重试。</p><p><strong>Q</strong>：选中文件夹后找不到文件？<br> A：检查文件格式是否为常见音视频，确认文件未被其他软件占用，路径和名称避免特殊符号。</p><p><strong>Q</strong>：运行时卡住或提示失败怎么办？<br> A：减少单次处理量，关闭占内存的软件，必要时结束任务后重新启动程序再试。</p><p><strong>Q</strong>：生成的文件名或Excel时长显示不对？<br> A：切换时长格式再运行一次，或重新勾选毫秒选项；若仍异常，检查原始文件是否损坏。</p><p><strong>Q</strong>：子文件夹没有被处理？<br> A：确认“是否穿透子文件夹”已勾选；未勾选时只会处理当前目录。</p><h3 id="程序截图" tabindex="-1">程序截图 <a class="header-anchor" href="#程序截图" aria-label="Permalink to &quot;程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251208225542176520574299262.png" alt=""></p><h3 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h3><p><strong>解压后会看到这两个文件，文件夹和程序必须放在同一文件夹下，程序可以创建快捷方式放到桌面，解压后的主文件夹名可以修改为其他名称，如下图所示的文件夹名不能修改。生成的excel文件会自动放到程序所在文件夹下如下图所示。</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251208231905176520714536865.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2251.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2251.html</a></p>',45)])])}const d=e(l,[["render",p]]);export{_ as __pageData,d as default};
